import{_ as t,o as s,c as a,ag as i}from"./chunks/framework.DMVuHR7L.js";const g=JSON.parse('{"title":"Screenshot pipeline (for agents)","description":"","frontmatter":{},"headers":[],"relativePath":"bots/screenshots.md","filePath":"bots/screenshots.md","lastUpdated":1778211710000}'),o={name:"bots/screenshots.md"};function n(r,e,h,l,c,d){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="screenshot-pipeline-for-agents" tabindex="-1">Screenshot pipeline (for agents) <a class="header-anchor" href="#screenshot-pipeline-for-agents" aria-label="Permalink to &quot;Screenshot pipeline (for agents)&quot;">​</a></h1><p>WebLogcat ships with a Playwright script that drives the <a href="./../features/simulator">simulator</a> and writes PNGs that both the docs site and the README depend on. Use it whenever:</p><ul><li>A UI change makes one of the existing screenshots look wrong.</li><li>A new widget / feature needs a hero shot.</li><li>The user asks you to refresh the README screenshot or any docs imagery.</li></ul><h2 id="where-the-script-lives" tabindex="-1">Where the script lives <a class="header-anchor" href="#where-the-script-lives" aria-label="Permalink to &quot;Where the script lives&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scripts/capture-feature-screenshots.spec.ts   # the captures</span></span>
<span class="line"><span>playwright.screenshots.config.ts              # standalone playwright config</span></span></code></pre></div><p>The script is <strong>not</strong> part of <code>npm run e2e</code> — it&#39;s invoked explicitly via <code>npm run docs:screenshots</code> so a flaky capture never blocks merges and a UI change can land without a forced regen.</p><h2 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Output path</th><th>Used by</th></tr></thead><tbody><tr><td><code>docs/features/img/&lt;slug&gt;.png</code></td><td>The matching <code>docs/features/&lt;slug&gt;.md</code> page on the docs site</td></tr><tr><td><code>docs/public/screenshot.png</code></td><td><code>README.md</code> hero image <strong>and</strong> <code>docs/index.md</code> hero block (single source of truth — the docs hero composition is also the README composition)</td></tr></tbody></table><h2 id="refreshing-screenshots" tabindex="-1">Refreshing screenshots <a class="header-anchor" href="#refreshing-screenshots" aria-label="Permalink to &quot;Refreshing screenshots&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Build the app so the preview server has fresh dist/.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Run the capture (uses vite preview at localhost:4173).</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:screenshots</span></span></code></pre></div><p>In environments where Playwright cannot fetch its pinned Chromium build, point at any preinstalled Chromium 1194+ binary:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CHROMIUM_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/pw-browsers/chromium-1194/chrome-linux/chrome</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:screenshots</span></span></code></pre></div><p>The script:</p><ol><li>Boots <code>vite preview</code> on port 4173.</li><li>Loads the app, clicks <strong>fake data</strong> to drop into the simulator.</li><li>For each capture, waits for the relevant DOM to settle, then writes the PNG to <code>docs/features/img/&lt;slug&gt;.png</code>.</li><li>The <code>dashboard-multi</code> capture additionally writes the same frame to <code>docs/public/screenshot.png</code> so the README hero stays in lockstep.</li></ol><p>After it runs, <strong>review every changed PNG</strong> before committing — open each one and confirm it shows what you expect (right widget, no error overlay, no clipped content, no console-error toast bleeding through). The script asserts that the canonical DOM elements rendered, but it can&#39;t tell you whether the composition is aesthetically right.</p><h2 id="refreshing-only-the-readme-hero" tabindex="-1">Refreshing only the README hero <a class="header-anchor" href="#refreshing-only-the-readme-hero" aria-label="Permalink to &quot;Refreshing only the README hero&quot;">​</a></h2><p>The hero comes out of a dedicated <code>README hero shot</code> capture that seeds <code>localStorage</code> with a deterministic four-widget composition before navigating, so the shot is bit-stable across regens.</p><p>The seeded state:</p><ul><li><strong>Tweaks</strong> — <code>accent: &#39;indigo&#39;</code> (matches the docs site&#39;s brand colour at hue 268), <code>compactMode: true</code>, <code>performanceMode: &#39;on&#39;</code>.</li><li><strong>Layout</strong> — Mirror left (≈32% width), then a column split on the right with Logcat on top (≈62% height) and Shell | Dumpsys at the bottom (50/50).</li><li><strong>Simulator hints</strong> — same convention as the feature shots: the &quot;Using simulated log data&quot; toast is waited out and the &quot;Simulated log stream&quot; badge is hidden via an injected <code>display:none</code> rule before the screenshot fires. Readers shouldn&#39;t mistake those onboarding affordances for product chrome.</li></ul><p>Re-run only the hero without churning the other PNGs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CHROMIUM_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">...</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --config=playwright.screenshots.config.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;README hero&#39;</span></span></code></pre></div><p>It writes to <code>docs/public/screenshot.png</code>, which the README and the docs landing both reference. If the user asks specifically for <em>the README screenshot</em>, that&#39;s this one.</p><p>To change the composition (different widgets, different ratios, a different accent), edit the <code>localStorage.setItem</code> block in <code>scripts/capture-feature-screenshots.spec.ts</code> under the <code>README hero shot</code> test. Layout payload shape lives in <a href="https://github.com/gabrielhuff/web-logcat/blob/main/src/lib/layout.ts" target="_blank" rel="noreferrer"><code>src/lib/layout.ts</code></a> (<code>weblogcat-dashboard-v2</code>); tweak shape lives in <a href="https://github.com/gabrielhuff/web-logcat/blob/main/src/lib/tweaks.ts" target="_blank" rel="noreferrer"><code>src/lib/tweaks.ts</code></a> (<code>weblogcat:tweaks:v1</code>).</p><h2 id="adding-a-new-capture" tabindex="-1">Adding a new capture <a class="header-anchor" href="#adding-a-new-capture" aria-label="Permalink to &quot;Adding a new capture&quot;">​</a></h2><p>Follow the existing pattern in <code>scripts/capture-feature-screenshots.spec.ts</code>:</p><ol><li>Add a <code>test(&#39;&lt;short description&gt;&#39;, async ({ page }) =&gt; { … })</code> block.</li><li>Boot the simulator with <code>await bootSimulator(page);</code>.</li><li>Add the widget if needed via <code>await addWidget(page, /Name/, &#39;.&lt;kind&gt;-widget&#39;);</code>.</li><li>Drive the widget to the state you want to capture; <strong>wait on a DOM signal</strong> that proves the state arrived (don&#39;t <code>setTimeout</code> — it&#39;ll flake).</li><li>Write the file via <code>await tile.screenshot({ path: out(&#39;&lt;slug&gt;&#39;) });</code> (tile-scoped) or <code>await page.screenshot({ path: out(&#39;&lt;slug&gt;&#39;), fullPage: false });</code> (full viewport).</li><li>Reference the new PNG from the matching <code>docs/features/&lt;page&gt;.md</code>.</li></ol><h2 id="real-device-only-flows" tabindex="-1">Real-device-only flows <a class="header-anchor" href="#real-device-only-flows" aria-label="Permalink to &quot;Real-device-only flows&quot;">​</a></h2><p>These cannot be captured by the script:</p><ul><li>Mirror&#39;s live screen frame — the simulator shows a static placeholder.</li><li>Files transfers (drag-out / drag-in) — no-ops in the simulator.</li><li>The WebUSB pairing dialog — Chromium chrome, not part of the page.</li></ul><p>For these, capture manually against a real device and commit the PNG under <code>docs/features/img/</code>. Flag the source in the alt-text so a future regen doesn&#39;t quietly replace it.</p>`,30)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
